// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

interface IPair {
    function getReserves() external view returns (uint112, uint112, uint32);
}

contract Minter {
    IPair public pair;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    uint256 public dailyMinted;

    event Minted(address indexed who, uint256 amount);

    constructor(address p) { pair = IPair(p); }

    // BUG: instantaneous AMM spot reserves used as a price oracle
    function _price() internal view returns (uint256) {
        (uint112 r0, uint112 r1, ) = pair.getReserves();
        return (uint256(r1) * 1e18) / uint256(r0);
    }

    function mint() external payable {
        uint256 amount = (msg.value * _price()) / 1e18;
        require(dailyMinted + amount <= 1_000_000 ether, "cap");
        balanceOf[msg.sender] += amount;
        totalSupply += amount;
        dailyMinted += amount;
        emit Minted(msg.sender, amount);
    }
}
